// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Dynamic Visual Shader by melcom (www.melcom-music.de)

const vec3 color1 = vec3(0.004, 0.122, 0.153); // Farbe 1 / Color 1
const vec3 color2 = vec3(0.094, 0.212, 0.255); // Farbe 2 / Color 2
const vec3 color3 = vec3(0.149, 0.333, 0.404); // Farbe 3 / Color 3
const vec3 color4 = vec3(0.745, 0.863, 0.965); // Farbe 4 / Color 4

// Hauptfunktion für das Bild / Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0; // Normierung der UV-Koordinaten für den gesamten Bildschirm / Normalize UV coordinates to cover the entire screen
    uv.x *= iResolution.x / iResolution.y; // Skalierung basierend auf dem Seitenverhältnis / Scale based on aspect ratio

    float time = iTime * 0.5; // Geschwindigkeit des Musters / Speed of the pattern

    // Dynamischer Muster-Effekt / Dynamic pattern effect
    float pattern = mod(time + length(uv) * 0.5, 2.0);
    vec3 color = vec3(0.5 + 0.5 * cos(pattern * 6.28 + uv.x * 4.0 + time),
                      0.5 + 0.5 * sin(pattern * 6.28 + uv.y * 4.0 + time + 2.0),
                      0.5 + 0.5 * cos(pattern * 6.28 + uv.y * 4.0 + time + 4.0));

    // Animations-Effekt / Animation effect
    float animation = sin(time * 5.0 + uv.x * 10.0) * 0.1;
    uv.y += animation;

    fragColor = vec4(color, 1.0); // Setzen der finalen Fragmentfarbe / Setting the final fragment color
}
